ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

def esc(s):
    s = s.replace("\\", "\\\\").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    s = s.replace("'", "\\'").replace('"', '\\"').replace("\n", "\\n")
    return s

def write(path, idx):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<!-- Generated by tools/strings.py. Edit that file, not this one. -->\n<resources>\n')
        for k in sorted(S):
            f.write(f'    <string name="{k}">{esc(S[k][idx])}</string>\n')
        f.write("</resources>\n")

used = set()
for dp, _, fs in os.walk(os.path.join(ROOT, "app/src/main/java")):
    for fn in fs:
        if fn.endswith(".kt"):
            used |= set(re.findall(r"R\.string\.([a-z_0-9]+)", open(os.path.join(dp, fn), encoding="utf-8").read()))
missing = sorted(used - set(S))
used |= {"shortcut_talk_short", "shortcut_talk_long"}
unused = sorted(set(S) - used)
bad = [k for k, (en, ta) in S.items() if sorted(re.findall(r"%\d\$[sd]", en)) != sorted(re.findall(r"%\d\$[sd]", ta))]
write(os.path.join(ROOT, "app/src/main/res/values/strings.xml"), 0)
write(os.path.join(ROOT, "app/src/main/res/values-ta/strings.xml"), 1)
print(f"strings: {len(S)}  used: {len(used)}  missing: {missing}  placeholder mismatch: {bad}  unused: {unused}")
sys.exit(1 if missing or bad else 0)
